<?php
/** Plugin Name: TEMP PS S1736g deploy av-dropship v1.21 + av-tiekimas v1.11 (1 dry / 2 deploy / 3 testas terra@gyvunai.lt / 9 atstato) */
add_action('wp_loaded', function(){
  if(!isset($_GET['ps_s1736g'])) return;
  $f=$_GET['ps_s1736g']; @set_time_limit(250); global $wpdb; $P=$wpdb->prefix; $r=['v'=>'S1736g','faze'=>$f];
  $F=[ 'petshop-av-dropship.php'=>['old'=>'a16f5a09742d7a92c96fb49550721fe3','new'=>'b2e49184bb599fd9db8bb4897283455f','b64'=>''],
       'petshop-av-tiekimas.php'=>['old'=>'cf7677a8c355c58cc79a489dae4114f1','new'=>'37d1128e5883f0463fec9f48eac6a48f','b64'=>''] ];
  $ARCH=dirname(rtrim(ABSPATH,'/')).'/ps-archyvas';
  $hb=function(){ $u=home_url('/?ps_hb='.time().rand(100,999)); $x=wp_remote_get($u,['timeout'=>25,'sslverify'=>false,'redirection'=>0]); return is_wp_error($x)?'ERR '.$x->get_error_message():wp_remote_retrieve_response_code($x); };
  try{
  if($f==='1'||$f==='2'){
    foreach($F as $fn=>$x){ $fp=WPMU_PLUGIN_DIR.'/'.$fn; $live=md5_file($fp); $nc=gzuncompress(base64_decode($x['b64']));
      $ok_tok=true; try{ token_get_all($nc,TOKEN_PARSE); }catch(Throwable $e){ $ok_tok='PARSE '.$e->getMessage().' @'.$e->getLine(); }
      $r['fail'][$fn]=['live'=>$live,'live_ok'=>$live===$x['old'],'new_md5_ok'=>md5($nc)===$x['new'],'tok'=>$ok_tok,'len'=>strlen($nc)];
      $F[$fn]['nc']=$nc; }
    $visi_ok=true; foreach($r['fail'] as $fn=>$z){ if(!($z['live_ok']&&$z['new_md5_ok']&&$z['tok']===true)) $visi_ok=false; }
    $r['visi_ok']=$visi_ok;
    if($f==='1'){
      foreach(['ambrosia','prins','quattro','belcor_tofu','zb'] as $s){ $rows=$wpdb->get_results($wpdb->prepare("SELECT s.product_id,s.supplier_sku,pm.meta_value sku FROM {$P}ps_sources s LEFT JOIN {$P}postmeta pm ON pm.post_id=s.product_id AND pm.meta_key='_sku' WHERE s.source=%s AND s.supplier_sku<>''",$s),ARRAY_A); $d=array_values(array_filter($rows,function($z){return strcasecmp(trim($z['supplier_sku']),trim((string)$z['sku']))!==0;})); $r['kiti'][$s]=['su_kodu'=>count($rows),'skiriasi'=>count($d),'pvz'=>array_slice($d,0,4)]; }
      $a=(array)get_option('ps_laisku_archyvas',[]);
      foreach($a as $l){ if($l['tema']==='užsakymas 2026-09-28' && strpos($l['kam'],'vetfarmas')!==false){ preg_match_all('~<b>(\d{3,6})</b>~',$l['html'],$m); $r['l0928_nr']=$m[1]; $r['l0928_kont']=$l['kont']; break; } }
      if(!empty($r['l0928_nr'])){ $in="'".implode("','",array_map('esc_sql',$r['l0928_nr']))."'"; $r['nr_meta']=$wpdb->get_results("SELECT order_id,meta_key,meta_value FROM {$P}wc_orders_meta WHERE meta_value IN($in) AND meta_key LIKE '%number%' LIMIT 40",ARRAY_A); }
      $r['p33']=$wpdb->get_row("SELECT * FROM {$P}ps_tiekimas WHERE id=33",ARRAY_A); $r['p33_eil']=$wpdb->get_results("SELECT * FROM {$P}ps_tiekimas_eil WHERE partija_id=33",ARRAY_A);
      $dp=WPMU_PLUGIN_DIR.'/petshop-dev-pastas.php'; if(file_exists($dp)){ foreach(file($dp) as $i=>$ln){ if(preg_match('/HTTP_HOST|petshop\.lt|pre_wp_mail|home_url|site_url|SERVER_NAME/',$ln)) $r['devpastas'][]=($i+1).': '.mb_substr(trim($ln),0,200); } }
      $r['arch']=$ARCH; $r['arch_yra']=is_dir($ARCH);
    }
    if($f==='2'){
      if(!$visi_ok){ $r['STOP']='patikros nepraėjo'; }
      else{
        foreach($F as $fn=>$x){ $fp=WPMU_PLUGIN_DIR.'/'.$fn; $bak=$ARCH.'/'.$fn.'.bak_s1736'; if(!file_exists($bak)) copy($fp,$bak); $r['bak'][$fn]=md5_file($bak); }
        foreach($F as $fn=>$x){ $fp=WPMU_PLUGIN_DIR.'/'.$fn; file_put_contents($fp,$x['nc']); if(function_exists('opcache_invalidate')) @opcache_invalidate($fp,true); $r['irasyta'][$fn]=md5_file($fp); }
        $h=$hb(); $r['hb']=$h;
        if(!is_int($h) || $h>=500){ foreach($F as $fn=>$x){ $fp=WPMU_PLUGIN_DIR.'/'.$fn; copy($ARCH.'/'.$fn.'.bak_s1736',$fp); if(function_exists('opcache_invalidate')) @opcache_invalidate($fp,true); } $r['ATSTATYTA']=true; $r['hb2']=$hb(); }
      }
    }
  }
  if($f==='3'||$f==='3s'){ $_GET['ids']='36310,36313,36314,36318,36321,36322,36544,36300'; $_GET['p']='33'; if($f==='3s') $_GET['siusti']=1;
    foreach($F as $fn=>$x) $r['live'][$fn]=md5_file(WPMU_PLUGIN_DIR.'/'.$fn)===$x['new'];
    $r['ver']=[ 'tiekejui'=>method_exists('Petshop_AV_Dropship','tiekejui'), 'csv'=>method_exists('Petshop_AV_Dropship','csv_failas') ];
    $ids=array_map('intval',array_filter(explode(',',$_GET['ids']??'')));
    $rm=new ReflectionMethod('Petshop_AV_Dropship','grupuoti'); $rm->setAccessible(true);
    $g=$rm->invoke(null,$ids,true); $uzs=$g['vf']??[];
    $part=$wpdb->get_row("SELECT * FROM {$P}ps_tiekimas WHERE id=".(int)($_GET['p']??0));
    $eil=$part?Petshop_AV_Tiekimas::partijos_eilutes($part->id):[];
    $ph=$part?Petshop_AV_Tiekimas::laisko_dalis($part,$eil,(string)$part->venipak_pack):'';
    $html=Petshop_AV_Dropship::laisko_html('vf',$uzs,'Ačiū :)',$ph);
    $csv=Petshop_AV_Dropship::csv_failas('vf',$uzs,$eil);
    $r['csv']=$csv?basename($csv):''; $r['csv_turinys']=$csv?file_get_contents($csv):'';
    $r['html']=$html;
    // kontrolė: DP pakas (#1130 → 36104, #1181 → 36306) ir ne-VF tiekėjas su EAN
    $g2=$rm->invoke(null,[36104,36306],true); $r['dp_kontrole']=$g2['vf']??[];
    if(!empty($_GET['siusti'])){
      $to='terra@gyvunai.lt';
      $ok=wp_mail($to,'[TESTAS – naujas formatas, VF negavo] užsakymas 2026-09-28',$html,['Content-Type: text/html; charset=UTF-8','From: UAB Avesa <terra@petshop.lt>'],$csv?[$csv]:[]);
      $r['wp_mail']=$ok; $r['klaida']=Petshop_AV_Dropship::$pasto_klaida;
    }
    if($csv) @unlink($csv);
  }
  if($f==='9'){
    foreach($F as $fn=>$x){ $fp=WPMU_PLUGIN_DIR.'/'.$fn; $bak=$ARCH.'/'.$fn.'.bak_s1736'; if(file_exists($bak)){ copy($bak,$fp); if(function_exists('opcache_invalidate')) @opcache_invalidate($fp,true); $r['atstatyta'][$fn]=md5_file($fp); } }
    $r['hb']=$hb();
  }
  }catch(Throwable $e){ $r['FATAL']=$e->getMessage().' @'.$e->getLine(); }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($r,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit;
}, 1);
